begin;
create table public.purchase_returns(id uuid primary key default gen_random_uuid(),purchase_item_id uuid not null references public.purchase_items(id),quantity numeric not null check(quantity>0),amount_minor bigint not null check(amount_minor>=0),reason text not null,idempotency_key uuid not null unique,created_by uuid default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
alter table public.purchase_returns enable row level security;
create policy returns_read on public.purchase_returns for select to authenticated using(public.has_permission('purchases.read'));
grant select on public.purchase_returns to authenticated;
create trigger returns_immutable before update or delete on public.purchase_returns for each row execute function public.immutable_record();
create trigger returns_audit after insert on public.purchase_returns for each row execute function public.audit_change();
create function public.return_purchase_item(payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare line public.purchase_items;p public.purchases;returned numeric;balance numeric;reserved numeric;qty numeric;amount bigint;paid bigint;prior_amount bigint;result uuid;existing public.purchase_returns;begin
 if not public.has_permission('purchases.approve') then raise insufficient_privilege;end if;
 select * into line from public.purchase_items where id=(payload->>'purchase_item_id')::uuid;if not found then raise no_data_found;end if;
 select * into p from public.purchases where id=line.purchase_id for update;if p.status<>'received' then raise exception 'Only received purchases can be returned';end if;
 qty=(payload->>'quantity')::numeric;if qty<=0 or length(payload->>'reason')<3 then raise exception 'Invalid purchase return';end if;
 select * into existing from public.purchase_returns where idempotency_key=(payload->>'idempotency_key')::uuid;if found then if existing.purchase_item_id<>line.id or existing.quantity<>qty or existing.reason<>payload->>'reason' then raise exception 'Idempotency key conflict';end if;return existing.id;end if;
 select coalesce(sum(quantity),0) into returned from public.purchase_returns where purchase_item_id=line.id;if returned+qty>line.quantity then raise exception 'Return exceeds received quantity';end if;
 amount=round(qty*line.rate_minor);select coalesce(sum(r.amount_minor),0) into prior_amount from public.purchase_returns r join public.purchase_items i on i.id=r.purchase_item_id where i.purchase_id=p.id;select coalesce(sum(amount_minor),0) into paid from public.supplier_payments where purchase_id=p.id;if paid>p.total_minor-prior_amount-amount then raise exception 'Review supplier refund before returning paid items';end if;
 perform 1 from public.materials where id=line.material_id for update;select coalesce(sum(quantity),0) into balance from public.stock_movements where material_id=line.material_id;select coalesce(sum(quantity),0) into reserved from public.stock_reservations where material_id=line.material_id and status='active';if balance-reserved<qty then raise exception 'Insufficient unreserved stock for return';end if;
 insert into public.purchase_returns(purchase_item_id,quantity,amount_minor,reason,idempotency_key) values(line.id,qty,amount,payload->>'reason',(payload->>'idempotency_key')::uuid) returning id into result;
 insert into public.stock_movements(material_id,quantity,unit_cost_minor,kind,purchase_id,note,idempotency_key) values(line.material_id,-qty,line.rate_minor,'return',p.id,payload->>'reason',gen_random_uuid());return result;end$$;
create function public.receivable_balances() returns table(order_id uuid,name text,customer_id uuid,total_minor bigint,paid_minor numeric,outstanding_minor numeric) language sql stable security invoker set search_path='' as $$select o.id,o.name,o.customer_id,o.total_minor,coalesce(p.amount,0),o.total_minor-coalesce(p.amount,0) from public.orders o left join(select order_id,sum(amount_minor) amount from public.customer_payments group by order_id)p on p.order_id=o.id where public.has_permission('finance.read')$$;
create function public.payable_balances() returns table(purchase_id uuid,name text,supplier_id uuid,total_minor bigint,returned_minor numeric,paid_minor numeric,outstanding_minor numeric) language sql stable security invoker set search_path='' as $$select p.id,p.name,p.supplier_id,p.total_minor,coalesce(r.amount,0),coalesce(s.amount,0),p.total_minor-coalesce(r.amount,0)-coalesce(s.amount,0) from public.purchases p left join(select purchase_id,sum(amount_minor) amount from public.supplier_payments group by purchase_id)s on s.purchase_id=p.id left join(select i.purchase_id,sum(r.amount_minor) amount from public.purchase_returns r join public.purchase_items i on i.id=r.purchase_item_id group by i.purchase_id)r on r.purchase_id=p.id where p.status='received' and public.has_permission('finance.read')$$;
create function public.worker_balances() returns table(worker_id uuid,name text,earned_minor numeric,paid_minor numeric,outstanding_minor numeric) language sql stable security invoker set search_path='' as $$select w.id,w.name,coalesce(e.amount,0),coalesce(p.amount,0),coalesce(e.amount,0)-coalesce(p.amount,0) from public.workers w left join(select worker_id,sum(amount_minor) amount from public.work_entries group by worker_id)e on e.worker_id=w.id left join(select worker_id,sum(amount_minor) amount from public.labour_payments group by worker_id)p on p.worker_id=w.id where public.has_permission('workers.read') and public.has_permission('finance.read')$$;
create or replace function public.post_payment(payment_kind text,payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;amount bigint;total bigint;paid bigint;returns bigint;target uuid;table_name text;field_name text;existing record;begin
 if not public.has_permission('finance.write') then raise insufficient_privilege;end if;amount=(payload->>'amount_minor')::bigint;if amount<=0 then raise exception 'Positive payment required';end if;
 if payment_kind='customer' then table_name='customer_payments';field_name='order_id';elsif payment_kind='supplier' then table_name='supplier_payments';field_name='purchase_id';elsif payment_kind='labour' then table_name='labour_payments';field_name='worker_id';else raise exception 'Invalid payment kind';end if;
 target=(payload->>field_name)::uuid;perform pg_advisory_xact_lock(hashtextextended(target::text,0));
 execute format('select id,%I as target,amount_minor,mode,reference from public.%I where idempotency_key=$1',field_name,table_name) into existing using (payload->>'idempotency_key')::uuid;
 if existing.id is not null then if existing.target<>target or existing.amount_minor<>amount or existing.mode<>payload->>'mode' or existing.reference<>payload->>'reference' then raise exception 'Idempotency key conflict';end if;return existing.id;end if;
 if payment_kind='customer' then select total_minor into total from public.orders where id=target and status<>'CANCELLED';
 elsif payment_kind='supplier' then select total_minor into total from public.purchases where id=target and status='received';select coalesce(sum(r.amount_minor),0) into returns from public.purchase_returns r join public.purchase_items i on i.id=r.purchase_item_id where i.purchase_id=target;total=total-returns;
 else select coalesce(sum(amount_minor),0) into total from public.work_entries where worker_id=target;end if;
 if total is null then raise exception 'Payment target not found or not posted';end if;
 execute format('select coalesce(sum(amount_minor),0) from public.%I where %I=$1',table_name,field_name) into paid using target;if paid+amount>total then raise exception 'Payment exceeds outstanding balance';end if;
 execute format('insert into public.%I(%I,amount_minor,mode,reference,idempotency_key) values($1,$2,$3,$4,$5) returning id',table_name,field_name) into result using target,amount,payload->>'mode',payload->>'reference',(payload->>'idempotency_key')::uuid;return result;end$$;
create function public.link_customer_identity(target uuid,verified_email text) returns void language plpgsql security definer set search_path='' as $$declare user_id uuid;begin
 if not public.has_permission('users.write') or not public.has_permission('customers.write') then raise insufficient_privilege;end if;
 select id into user_id from auth.users where lower(email)=lower(verified_email) and email_confirmed_at is not null;if not found then raise exception 'Confirmed account with this email was not found';end if;
 update public.customers set user_id=user_id where id=target;end$$;
-- Use a different PL/pgSQL variable name to avoid column ambiguity.
create or replace function public.link_customer_identity(target uuid,verified_email text) returns void language plpgsql security definer set search_path='' as $$declare linked_user uuid;begin
 if not public.has_permission('users.write') or not public.has_permission('customers.write') then raise insufficient_privilege;end if;
 select id into linked_user from auth.users where lower(email)=lower(verified_email) and email_confirmed_at is not null;if not found then raise exception 'Confirmed account with this email was not found';end if;
 update public.customers set user_id=linked_user where id=target;if not found then raise no_data_found;end if;end$$;
grant execute on function public.return_purchase_item(jsonb),public.receivable_balances(),public.payable_balances(),public.worker_balances(),public.link_customer_identity(uuid,text) to authenticated;
revoke execute on function public.return_purchase_item(jsonb),public.receivable_balances(),public.payable_balances(),public.worker_balances(),public.link_customer_identity(uuid,text) from public;
commit;
